import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·13","description":"易小帖 - 卷三·13","frontmatter":{"title":"卷三·13","description":"易小帖 - 卷三·13"},"headers":[],"relativePath":"classics/yixiaotie/081.md","filePath":"classics/yixiaotie/081.md"}'),o={name:"classics/yixiaotie/081.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·13",tabindex:"-1"},[r("卷三·13 "),e("a",{class:"header-anchor",href:"#卷三·13","aria-label":"Permalink to “卷三·13”"},"​")],-1),e("p",null,"易卦原無數，其有數者總以《大傳》卦位為言，如坎之一，乾之六，以坎位正北，乾位西北，與鄭康成所註大衍之數「天一生水於北，地六成之」相合，故雲：若乾一兌二，何據乎？陳摶作先天圖位，因兩儀四象畫卦而設，故陰陽老少並非四象，而圖以四象為老陰、老陽、少陰、少陽，因之以乾為老陽，坤為老陰，震坎艮為少陽，巽離兌為少陰。若據唐崔憬老少之數，則乾九老陽，震七長陽，坎五中陽，艮三少陽，坤六老陰，巽八長陰，離十中陰，兌二少陰，與乾一兌二離三震四巽五坎六艮七坤八之數全然不合。若以揲蓍之老少言，則乾九老陽，坤六老陰，震坎艮皆七少陽，巽離兌皆八少陰。其於乾一兌二諸數又不合。然而揲蓍之數，宋人所稔講也。乾九坤六，兩少七八，程朱諸儒皆取用為說者也。於是巧為曲全者，造作四象八卦位數圖，謂位從一至四順數，從九至六逆數，乾為太陽，則位一而數九。巽離兌為少陰，則位二而數八。震坎艮為少陽，則位三而數七。坤為太陰，則位八而數六。其位無五而數無十，正以合之圖書八卦中央無位數之旨，可謂匠心巧妙矣。然以合之先天之數，則乾兌離坎艮坤，六卦尚可強合，而以震三之數當位二數八之陰，巽五之數當位三數七之陽，則鵠黑烏白矣。六經以聖言為主，非聖之言，雖多方鏝飾，無一而可。若卦位之數，經無明文，但就《說卦》推之，則震一巽二，離三坤四，兌五乾六，坎七艮八，此斷斷不易者。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
